WITH filtered_customers AS (SELECT * FROM customers WHERE segment <> 'Corporate'), SignupCohortSummary AS (SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, ROUND(STDDEV(credit_limit), 2) AS stddev_credit_limit FROM filtered_customers GROUP BY CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT signup_cohort, stddev_credit_limit FROM SignupCohortSummary WHERE stddev_credit_limit > 55 ORDER BY signup_cohort
